#ifndef FFPMCCTTILDE_H
#define FFPMCCTTILDE_H

#include <complex>
#include <FArray.hpp>

extern std::complex<double> FFPMccTtilde(int j1, int j2, int j3, int j4, int j5, int j6, FArray2D<std::complex<double>>& za, FArray2D<std::complex<double>>& zb);

extern "C" {
  extern std::complex<double> FFPMccTtilde_wrapper(int j1, int j2, int j3, int j4, int j5, int j6, std::complex<double>* fza, std::complex<double>* fzb);
}

#endif

#include <FFPMccTtilde.hpp>
#include <cmath>
#include <complex>
#include <FArray.hpp>
#include <mxpart_mod.hpp>
#include <W1jet.hpp>

// Z. Bern, L. Dixon, D.A. Kosower, e-Print:hep-ph/9708239
// Eq.10.18
std::complex<double> FFPMccTtilde(int j1, int j2, int j3, int j4, int j5, int j6, FArray2D<std::complex<double>>& za, FArray2D<std::complex<double>>& zb) {
  auto zab2 = [&](int j1, int j2, int j3, int j4) {
    return za(j1, j2) * zb(j2, j4) + za(j1, j3) * zb(j3, j4);
  };
  auto zab = [&](int j1, int j2, int j3) {
    return za(j1, j2) * zb(j2, j3);
  };

  std::complex<double> FFPMccTtilde; // @coverage-probe
  FFPMccTtilde =
      1.0 / (zab2(j1, j2, j3, j4) * zab2(j3, j1, j4, j2))
      * (0.5 * (zab(j4, j1, j3) - zab(j4, j2, j3)) * zab2(j5, j1, j4, j6)
         + zab(j5, j1, j3) * zab(j4, j2, j6)

         + zab2(j4, j1, j2, j3) / zab2(j3, j1, j2, j4)
           * (zab(j5, j2, j4) * zab(j3, j1, j6)
              - zab(j3, j1, j4) * (zab(j5, j2, j6) - zab(j5, j3, j6))))
      - zb(j1, j3) * za(j4, j5) * zab2(j2, j1, j3, j6)
        / (zab2(j3, j1, j2, j4) * t(j1, j2, j3));

  return FFPMccTtilde;
}

extern "C" {
  std::complex<double> FFPMccTtilde_wrapper(int j1, int j2, int j3, int j4, int j5, int j6, std::complex<double>* fza, std::complex<double>* fzb) {
    using namespace mxpart_mod;

    FArray2D<std::complex<double>> za(fza, mxpart, mxpart);
    FArray2D<std::complex<double>> zb(fzb, mxpart, mxpart);

    return FFPMccTtilde(j1, j2, j3, j4, j5, j6, za, zb);
  }
}

